--
-- Table structure for table `md_expense_item`
--

DROP TABLE IF EXISTS `md_expense_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `md_expense_item` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `tenant_id` bigint NOT NULL COMMENT '租户ID【多租户隔离字段】',
  `item_code` varchar(64) NOT NULL COMMENT '费用项目编码',
  `item_name` varchar(200) NOT NULL COMMENT '费用项目名称,如 市内交通费',
  `parent_id` bigint NOT NULL DEFAULT '0' COMMENT '上级ID,0为顶级',
  `ancestors` varchar(500) DEFAULT '' COMMENT '祖级路径',
  `item_level` int NOT NULL DEFAULT '1' COMMENT '层级',
  `is_leaf` tinyint NOT NULL DEFAULT '1' COMMENT '是否末级:仅末级可被单据引用',
  `bill_type` varchar(50) DEFAULT NULL COMMENT '适用单据类型,逗号分隔:TRAVEL差旅/DAILY日常/ENTERTAIN招待/PUBLIC对公',
  `subject_id` bigint DEFAULT NULL COMMENT '默认会计科目ID(生成凭证用)',
  `default_tax_rate` decimal(6,4) DEFAULT NULL COMMENT '默认税率,如 0.0600',
  `need_invoice` tinyint NOT NULL DEFAULT '1' COMMENT '是否必须上传发票:0否 1是',
  `need_attach` tinyint NOT NULL DEFAULT '0' COMMENT '是否必须上传附件:0否 1是',
  `budget_control` tinyint NOT NULL DEFAULT '0' COMMENT '是否受预算控制:0否 1是',
  `std_control` varchar(20) NOT NULL DEFAULT 'NONE' COMMENT '标准控制:NONE不控/WARN超标提醒/BLOCK超标禁止',
  `sort` int NOT NULL DEFAULT '0' COMMENT '排序',
  `status` varchar(20) NOT NULL DEFAULT 'NORMAL' COMMENT '状态:NORMAL/DISABLED',
  `remark` varchar(500) DEFAULT NULL,
  `create_by` bigint DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` tinyint NOT NULL DEFAULT '0',
  `requires_pre_approval` tinyint DEFAULT '0' COMMENT '是否需事前审批',
  `requires_contract` tinyint DEFAULT '0' COMMENT '是否需关联合同',
  `requires_project` tinyint DEFAULT '0' COMMENT '是否需关联项目',
  `budget_control_type` varchar(20) DEFAULT 'NONE' COMMENT '预算控制类型 RIGID/FLEXIBLE/NONE',
  `approval_complexity` int DEFAULT '1' COMMENT '审批复杂度1-5',
  `has_tax` tinyint DEFAULT '1' COMMENT '1含税0不含税',
  `default_gl_account` varchar(100) DEFAULT NULL COMMENT '默认总账科目',
  `sort_order` int DEFAULT '0' COMMENT '排序号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tenant_item_code` (`tenant_id`,`item_code`),
  KEY `idx_tenant` (`tenant_id`),
  KEY `idx_tenant_parent` (`tenant_id`,`parent_id`)
) ENGINE=InnoDB AUTO_INCREMENT=543 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='费用项目';
/*!40101 SET character_set_client = @saved_cs_client */;

